SELECT MAX(sixes) AS max_six_in_an_innings
FROM (
    SELECT match_id, inning, striker_id, SUM(CASE WHEN runs_scored = 6 THEN 1 ELSE 0 END) AS sixes
    FROM Deliveries
    WHERE match_id IN (
        SELECT match_id FROM Matches
        WHERE season = '2026'
    )
    GROUP BY match_id, inning, striker_id
) AS player_innings;

